SELECT CASE WHEN amount >= 3200 THEN 'PREMIUM' ELSE 'STANDARD' END AS amount_tier, DATE_TRUNC('MONTH', txn_time) AS activity_month, ROUND(AVG(amount), 2) AS avg_amount, MAX(txn_time) AS last_txn_time, (UNIX_TIMESTAMP(MAX(txn_time)) - UNIX_TIMESTAMP(MIN(txn_time))) / 60 AS duration_min, COUNT(DISTINCT txn_type) AS distinct_txn_types, COUNT(CASE WHEN txn_type = 'CREDIT' THEN 1 END) AS credit_count, GROUPING_ID() AS grouping_level FROM transactions GROUP BY GROUPING SETS ((CASE WHEN amount >= 3200 THEN 'PREMIUM' ELSE 'STANDARD' END, DATE_TRUNC('MONTH', txn_time)), (CASE WHEN amount >= 3200 THEN 'PREMIUM' ELSE 'STANDARD' END)) HAVING COUNT(DISTINCT txn_type) >= 1 ORDER BY avg_amount ASC NULLS FIRST
